package com.qinghe.life.service.impl;
import com.baomidou.mybatisplus.core.metadata.IPage; import com.baomidou.mybatisplus.core.toolkit.Wrappers; import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.qinghe.life.common.PageResult; import com.qinghe.life.dto.*; import com.qinghe.life.entity.*; import com.qinghe.life.exception.BusinessException; import com.qinghe.life.mapper.*; import com.qinghe.life.service.AdminDormCheckinService; import com.qinghe.life.utils.AdminContext; import com.qinghe.life.vo.*;
import java.time.LocalDateTime; import java.util.*; import java.util.stream.Collectors; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminDormCheckinServiceImpl implements AdminDormCheckinService {
 private final DormCheckinMapper checkins; private final StudentProfileMapper profiles; private final AssetSetMapper sets; private final DormBedMapper beds; private final DormRoomMapper rooms; private final BuildingMapper buildings; private final CampusMapper campuses; private final com.qinghe.life.service.DormCheckinLifecycle lifecycle;
 public AdminDormCheckinServiceImpl(DormCheckinMapper c,StudentProfileMapper p,AssetSetMapper s,DormBedMapper b,DormRoomMapper r,BuildingMapper g,CampusMapper a,com.qinghe.life.service.DormCheckinLifecycle l){checkins=c;profiles=p;sets=s;beds=b;rooms=r;buildings=g;campuses=a;lifecycle=l;}
 public PageResult<AdminDormCheckinVO> page(AdminDormCheckinQuery q){ admin(); List<Long> users=null; if(text(q.getStudentName())!=null||text(q.getStudentNo())!=null){List<StudentProfile> ps=profiles.selectList(Wrappers.<StudentProfile>lambdaQuery().eq(StudentProfile::getCurrentFlag,1).like(text(q.getStudentName())!=null,StudentProfile::getRealName,text(q.getStudentName())).like(text(q.getStudentNo())!=null,StudentProfile::getStudentNo,text(q.getStudentNo())));users=ps.stream().map(StudentProfile::getUserId).collect(Collectors.toList());if(users.isEmpty())return PageResult.empty(q.getPage(),q.getSize());} String campus=campusName(q.getCampusId()); String building=buildingName(q.getBuildingId()); IPage<DormCheckin> data=checkins.selectPage(new Page<DormCheckin>(q.getPage(),q.getSize()),Wrappers.<DormCheckin>lambdaQuery().in(users!=null,DormCheckin::getUserId,users).eq(campus!=null,DormCheckin::getCampusNameSnapshot,campus).eq(building!=null,DormCheckin::getBuildingNameSnapshot,building).eq(text(q.getRoomNo())!=null,DormCheckin::getRoomNoSnapshot,text(q.getRoomNo())).eq(text(q.getStudentStatus())!=null,DormCheckin::getStudentStatusSnapshot,text(q.getStudentStatus())).eq("ACTIVE".equals(q.getCheckinStatus()),DormCheckin::getActiveFlag,1).isNull("CHECKED_OUT".equals(q.getCheckinStatus()),DormCheckin::getActiveFlag).orderByDesc(DormCheckin::getCheckinTime)); return new PageResult<AdminDormCheckinVO>(data.getRecords().stream().map(x->view(x,false)).collect(Collectors.toList()),data.getTotal(),data.getCurrent(),data.getSize()); }
 public AdminDormCheckinVO detail(Long id){admin();DormCheckin item=checkins.selectById(id);if(item==null)throw new BusinessException(404,"入住记录不存在");return view(item,true);}
 @Transactional(rollbackFor=Exception.class) public void checkout(Long id,DormCheckoutRequest r){Long admin=admin();DormCheckin item=lifecycle.lockActiveCheckin(id);lifecycle.checkout(item,r.getReason(),admin,"CHECKED_OUT");}
 @Transactional(rollbackFor=Exception.class) public void transfer(Long id,DormTransferRequest r){Long admin=admin();DormCheckin old=activeForUpdate(id);if(old.getDormBedId().equals(r.getTargetBedId()))throw new BusinessException("原床位和目标床位不能相同");DormBed target=beds.selectById(r.getTargetBedId());if(target==null)throw new BusinessException(404,"目标床位不存在");if(!Integer.valueOf(1).equals(target.getStatus()))throw new BusinessException("目标床位已停用");DormRoom room=rooms.selectById(target.getDormRoomId());if(room==null||!Integer.valueOf(1).equals(room.getStatus()))throw new BusinessException("目标寝室已停用");Building building=buildings.selectById(room.getBuildingId());Campus campus=campuses.selectById(room.getCampusId());if(building==null||campus==null||!Integer.valueOf(1).equals(building.getStatus())||!Integer.valueOf(1).equals(campus.getStatus())||!room.getCampusId().equals(building.getCampusId()))throw new BusinessException("目标宿舍目录不可用");AssetSet targetSet=sets.selectOne(Wrappers.<AssetSet>lambdaQuery().eq(AssetSet::getDormBedId,target.getId()).last("FOR UPDATE"));if(targetSet==null||!"AVAILABLE".equals(targetSet.getStatus()))throw new BusinessException("目标床位没有可用资产套装");if(checkins.selectCount(Wrappers.<DormCheckin>lambdaQuery().eq(DormCheckin::getDormBedId,target.getId()).eq(DormCheckin::getActiveFlag,1))>0)throw new BusinessException("目标床位已被占用");AssetSet oldSet=setForUpdate(old.getAssetSetId());close(old,r.getReason(),admin,"TRANSFERRED");oldSet.setStatus("AVAILABLE");updateAssetState(oldSet,"原资产套装释放失败，请稍后重试");DormCheckin next=new DormCheckin();next.setUserId(old.getUserId());next.setStudentProfileId(old.getStudentProfileId());next.setDormBedId(target.getId());next.setAssetSetId(targetSet.getId());next.setPreviousCheckinId(old.getId());next.setCheckinSource("ADMIN_TRANSFER");next.setCheckinStatus("ACTIVE");next.setActiveFlag(1);next.setStudentNoSnapshot(old.getStudentNoSnapshot());next.setStudentStatusSnapshot(old.getStudentStatusSnapshot());next.setCampusNameSnapshot(campus.getCampusName());next.setBuildingCodeSnapshot(building.getBuildingCode());next.setBuildingNameSnapshot(building.getBuildingName());next.setRoomNoSnapshot(room.getRoomNo());next.setBedNoSnapshot(target.getBedNo());next.setAssetSetNoSnapshot(targetSet.getAssetSetNo());next.setOperatorAdminId(admin);try{checkins.insert(next);}catch(DuplicateKeyException e){throw new BusinessException(409,"目标床位已被其他操作占用，请刷新后重试");}targetSet.setStatus("OCCUPIED");updateAssetState(targetSet,"目标资产套装占用失败，请稍后重试");}
 public List<AvailableDormBedVO> availableBeds(Long campusId,Long buildingId,Long roomId){admin();return sets.selectList(Wrappers.<AssetSet>lambdaQuery().eq(AssetSet::getStatus,"AVAILABLE")).stream().map(s->{DormBed b=beds.selectById(s.getDormBedId());if(b==null||!Integer.valueOf(1).equals(b.getStatus()))return null;DormRoom r=rooms.selectById(b.getDormRoomId());if(r==null||!Integer.valueOf(1).equals(r.getStatus())||campusId!=null&&!campusId.equals(r.getCampusId())||buildingId!=null&&!buildingId.equals(r.getBuildingId())||roomId!=null&&!roomId.equals(r.getId()))return null;Building g=buildings.selectById(r.getBuildingId());Campus c=campuses.selectById(r.getCampusId());if(g==null||c==null||!Integer.valueOf(1).equals(g.getStatus())||!Integer.valueOf(1).equals(c.getStatus())||checkins.selectCount(Wrappers.<DormCheckin>lambdaQuery().eq(DormCheckin::getDormBedId,b.getId()).eq(DormCheckin::getActiveFlag,1))>0)return null;AvailableDormBedVO v=new AvailableDormBedVO();v.setBedId(b.getId());v.setCampusId(c.getId());v.setBuildingId(g.getId());v.setRoomId(r.getId());v.setCampusName(c.getCampusName());v.setBuildingName(g.getBuildingName());v.setRoomNo(r.getRoomNo());v.setBedNo(b.getBedNo());v.setAssetSetNo(s.getAssetSetNo());return v;}).filter(Objects::nonNull).collect(Collectors.toList());}
 private DormCheckin activeForUpdate(Long id){DormCheckin x=checkins.selectOne(Wrappers.<DormCheckin>lambdaQuery().eq(DormCheckin::getId,id).eq(DormCheckin::getActiveFlag,1).last("FOR UPDATE"));if(x==null)throw new BusinessException("该入住记录已退宿或不存在");return x;} private AssetSet setForUpdate(Long id){AssetSet x=sets.selectOne(Wrappers.<AssetSet>lambdaQuery().eq(AssetSet::getId,id).last("FOR UPDATE"));if(x==null)throw new BusinessException("入住资产套装不存在");return x;} private void close(DormCheckin x,String reason,Long admin,String status){LocalDateTime time=LocalDateTime.now();String checkoutReason=text(reason);if(checkins.update(null,Wrappers.<DormCheckin>lambdaUpdate().eq(DormCheckin::getId,x.getId()).eq(DormCheckin::getActiveFlag,1).set(DormCheckin::getCheckoutTime,time).set(DormCheckin::getCheckoutReason,checkoutReason).set(DormCheckin::getCheckinStatus,status).set(DormCheckin::getActiveFlag,null).set(DormCheckin::getOperatorAdminId,admin))!=1)throw new BusinessException("入住记录更新失败，请稍后重试");x.setCheckoutTime(time);x.setCheckoutReason(checkoutReason);x.setCheckinStatus(status);x.setActiveFlag(null);x.setOperatorAdminId(admin);} private void updateAssetState(AssetSet set,String message){if(sets.updateById(set)!=1)throw new BusinessException(message);} private Long admin(){Long id=AdminContext.getAdminId();if(id==null)throw new BusinessException(401,"管理员登录已过期");return id;} private String campusName(Long id){if(id==null)return null;Campus x=campuses.selectById(id);return x==null?"__NOT_FOUND__":x.getCampusName();} private String buildingName(Long id){if(id==null)return null;Building x=buildings.selectById(id);return x==null?"__NOT_FOUND__":x.getBuildingName();} private String text(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
 private AdminDormCheckinVO view(DormCheckin x,boolean detail){AdminDormCheckinVO v=new AdminDormCheckinVO();v.setId(x.getId());StudentProfile p=profiles.selectOne(Wrappers.<StudentProfile>lambdaQuery().eq(StudentProfile::getId,x.getStudentProfileId()));v.setRealName(p==null?"已归档学生":p.getRealName());v.setMaskedStudentNo(mask(x.getStudentNoSnapshot()));v.setCollegeName(p==null?null:p.getCollegeName());v.setMajorName(p==null?null:p.getMajorName());v.setClassName(p==null?null:p.getClassName());v.setStudentStatus(x.getStudentStatusSnapshot());v.setCampusName(x.getCampusNameSnapshot());v.setBuildingName(x.getBuildingNameSnapshot());v.setRoomNo(x.getRoomNoSnapshot());v.setBedNo(x.getBedNoSnapshot());v.setAssetSetNo(x.getAssetSetNoSnapshot());v.setCheckinTime(x.getCheckinTime());v.setCheckoutTime(x.getCheckoutTime());v.setCheckoutReason(detail?x.getCheckoutReason():null);v.setCheckinStatus(x.getCheckinStatus());v.setMaskedContactPhone(detail&&p!=null?phone(p.getContactPhone()):null);return v;} private String mask(String s){return s==null||s.length()<5?"***":s.substring(0,2)+"***"+s.substring(s.length()-2);} private String phone(String s){return s==null?null:s.replaceAll("^(\\d{3})\\d+(\\d{4})$","$1****$2");}
}
